export type AgentMachineState =
  | 'IDLE'
  | 'INBOX_QUEUED'
  | 'CLAIMED'
  | 'EXECUTING_PROTOCOL'
  | 'PROOF_ATTACHED'
  | 'OUTBOX_DISPATCHED'
  | 'YIELD_AUDITED'
  | 'HALTED_VIOLATION';

export type ProtocolEvent =
  | 'ENQUEUE_INBOX'
  | 'ACQUIRE_CLAIM'
  | 'RUN_AGENT_KIT'
  | 'ATTACH_PROOF'
  | 'DISPATCH_OUTBOX'
  | 'RECORD_YIELD'
  | 'FLAG_VIOLATION'
  | 'RESET_HEADLESS';

export type YieldGrade = 'Exceeds' | 'On Target' | 'Sub-Target' | 'Critical Deficit';

export interface YieldCalculation {
  yieldRatio: number;
  yieldPercent: number;
  delta: number;
  grade: YieldGrade;
}

export interface InboxMessage {
  id: string;
  timestamp: string;
  eventType: ProtocolEvent;
  sender: string;
  payloadSummary: string;
  processed: boolean;
}

export interface OutboxMessage {
  id: string;
  timestamp: string;
  eventType: string;
  recipient: string;
  proofRef: string;
  yieldSnapshot: string;
  delivered: boolean;
}

export interface MemoryEntry {
  id: string;
  key: string;
  scope: 'Estate-Global' | 'Protocol-State' | 'Claim-Ledger';
  valueSummary: string;
  version: number;
  updatedAt: string;
}

export interface SpecialistAgent {
  id: string;
  name: string;
  squad: string;
  estateDomain: string;
  protocolId: string;
  machineState: AgentMachineState;
  headlessRuntime: string;
  laptopDependency: 'Zero (Headless Worker)';
  quadLayerConfig: {
    protocolSpec: string;
    stateMachineSpec: string;
    memoryStoreId: string;
    agentKitVersion: string;
  };
  inbox: InboxMessage[];
  outbox: OutboxMessage[];
  memoryKeys: number;
  evalScore: number;
  trainingGeneration: string;
}

export type InstructionStage =
  | 'Instruction Issued'
  | 'Claimed by Specialist'
  | 'Proof Verified'
  | 'Outcome Measured'
  | 'Founder Approved'
  | 'Revision Requested';

