/**
 * Pure calculation of Yield (Actual Outcome vs Expected Outcome).
 * Handles both higher-is-better (e.g. NOI recovery, covenants audited) and lower-is-better (e.g. cycle time, variance error).
 */
export function calculateYield(
  expectedValue: number,
  actualValue: number,
  lowerIsBetter = false
): YieldCalculation {
  if (expectedValue <= 0 || Number.isNaN(expectedValue) || Number.isNaN(actualValue)) {
    return {
      yieldRatio: 0,
      yieldPercent: 0,
      delta: 0,
      grade: 'Critical Deficit',
    };
  }

  let rawRatio: number;
  let delta: number;

  if (lowerIsBetter) {
    if (actualValue <= 0) {
      rawRatio = 1.25;
    } else {
      rawRatio = expectedValue / actualValue;
    }
    delta = Number((expectedValue - actualValue).toFixed(2));
  } else {
    rawRatio = actualValue / expectedValue;
    delta = Number((actualValue - expectedValue).toFixed(2));
  }

  const boundedRatio = Math.max(0, Math.min(rawRatio, 2.5));
  const yieldPercent = Math.round(boundedRatio * 1000) / 10;

  let grade: YieldGrade;
  if (yieldPercent >= 105) {
    grade = 'Exceeds';
  } else if (yieldPercent >= 95) {
    grade = 'On Target';
  } else if (yieldPercent >= 80) {
    grade = 'Sub-Target';
  } else {
    grade = 'Critical Deficit';
  }

  return {
    yieldRatio: Number(boundedRatio.toFixed(3)),
    yieldPercent,
    delta,
    grade,
  };
}

/**
 * Deterministic Event-Driven State Machine transition table for Headless Specialist Agents.
 */
const STATE_TRANSITION_MAP: Record<
  AgentMachineState,
  Partial<Record<ProtocolEvent, { next: AgentMachineState; reason: string; outboxAction?: string }>>
> = {
  IDLE: {
    ENQUEUE_INBOX: {
      next: 'INBOX_QUEUED',
      reason: 'Private Inbox accepted signed Estate instruction payload.',
    },
  },
  INBOX_QUEUED: {
    ACQUIRE_CLAIM: {
      next: 'CLAIMED',
      reason: 'Specialist locked deterministic execution claim in Quad-Layer.',
    },
    FLAG_VIOLATION: {
      next: 'HALTED_VIOLATION',
      reason: 'Schema mismatch detected in incoming inbox event.',
    },
  },
  CLAIMED: {
    RUN_AGENT_KIT: {
      next: 'EXECUTING_PROTOCOL',
      reason: 'Agent Kit invoked headless Estate tools without human/laptop loop.',
    },
    FLAG_VIOLATION: {
      next: 'HALTED_VIOLATION',
      reason: 'Claim lock expired or precondition invariant failed.',
    },
  },
  EXECUTING_PROTOCOL: {
    ATTACH_PROOF: {
      next: 'PROOF_ATTACHED',
      reason: 'Cryptographic ledger proof and artifact diff verified against protocol.',
    },
    FLAG_VIOLATION: {
      next: 'HALTED_VIOLATION',
      reason: 'Execution invariant breach; halted safely before side effects.',
    },
  },
  PROOF_ATTACHED: {
    DISPATCH_OUTBOX: {
      next: 'OUTBOX_DISPATCHED',
      reason: 'Signed outcome + proof emitted to Private Outbox queue.',
      outboxAction: 'EMIT_VERIFIED_PROOF_BUNDLE',
    },
    FLAG_VIOLATION: {
      next: 'HALTED_VIOLATION',
      reason: 'Proof artifact failed completeness verification.',
    },
  },
  OUTBOX_DISPATCHED: {
    RECORD_YIELD: {
      next: 'YIELD_AUDITED',
      reason: 'Outcome vs. Expected Outcome yield committed for Founder Review.',
      outboxAction: 'COMMIT_YIELD_LEDGER',
    },
    RESET_HEADLESS: {
      next: 'IDLE',
      reason: 'Worker cycle completed; returned to headless standby.',
    },
  },
  YIELD_AUDITED: {
    RESET_HEADLESS: {
      next: 'IDLE',
      reason: 'Yield archived in Estate Memory; agent ready for next Inbox event.',
    },
    ENQUEUE_INBOX: {
      next: 'INBOX_QUEUED',
      reason: 'Next instruction queued directly from audited state.',
    },
  },
  HALTED_VIOLATION: {
    RESET_HEADLESS: {
      next: 'IDLE',
      reason: 'State machine reset after protocol audit clearance.',
    },
  },
};

export function transitionAgentState(
  currentState: AgentMachineState,
  event: ProtocolEvent
): {
  nextState: AgentMachineState;
  valid: boolean;
  reason: string;
  outboxAction?: string;
} {
  const allowed = STATE_TRANSITION_MAP[currentState]?.[event];
  if (!allowed) {
    return {
      nextState: currentState,
      valid: false,
      reason: `Event ${event} is prohibited from state ${currentState} under strict Estate Protocol.`,
    };
  }
  return {
    nextState: allowed.next,
    valid: true,
    reason: allowed.reason,
    outboxAction: allowed.outboxAction,
  };
}

export function getNextCanonicalEvent(state: AgentMachineState): ProtocolEvent {
  switch (state) {
    case 'IDLE':
      return 'ENQUEUE_INBOX';
    case 'INBOX_QUEUED':
      return 'ACQUIRE_CLAIM';
    case 'CLAIMED':
      return 'RUN_AGENT_KIT';
    case 'EXECUTING_PROTOCOL':
      return 'ATTACH_PROOF';
    case 'PROOF_ATTACHED':
      return 'DISPATCH_OUTBOX';
    case 'OUTBOX_DISPATCHED':
      return 'RECORD_YIELD';
    case 'YIELD_AUDITED':
    case 'HALTED_VIOLATION':
      return 'RESET_HEADLESS';
  }
}

/**
 * Validates that a specialist's Claim and Proof artifact satisfy strict Estate protocol requirements.
 */
export function validateInstructionProof(
  claimStatement: string,
  proofArtifact: string,
  protocolId: string
): {
  valid: boolean;
  completenessScore: number;
  missingElements: string[];
} {
  const missingElements: string[] = [];
  const trimmedClaim = claimStatement.trim();
  const trimmedProof = proofArtifact.trim();

  if (trimmedClaim.length < 12) {
    missingElements.push('Explicit specialist claim statement (min 12 chars)');
  }
  if (trimmedProof.length < 10) {
    missingElements.push('Verifiable proof reference or artifact hash');
  }
  if (!protocolId.trim().startsWith('PRT-')) {
    missingElements.push('Canonical Estate Protocol identifier (PRT-*)');
  }

  const hasHashOrRef =
    trimmedProof.includes('sha256:') ||
    trimmedProof.includes('PRF-') ||
    trimmedProof.includes('LEDGER-') ||
    trimmedProof.includes('DIFF-');

  if (trimmedProof.length >= 10 && !hasHashOrRef) {
    missingElements.push('Structured proof token (PRF-*, LEDGER-*, DIFF-*, or sha256:)');
  }

  const completenessScore = Math.max(0, 100 - missingElements.length * 25);
  return {
    valid: missingElements.length === 0,
    completenessScore,
    missingElements,
  };
}

/**
 * Computes aggregate Fleet & Yield metrics across all active instructions, specialists, and evals.
 */
export function computeFleetMetrics(
  instructions: InstructionRecord[],
  agents: SpecialistAgent[],
  evals: EvalScenario[]
): FleetSummaryMetrics {
  const totalInstructions = instructions.length;
  const averageYieldPercent =
    totalInstructions === 0
      ? 0
      : Math.round(
          (instructions.reduce((sum, item) => sum + item.yieldPercent, 0) / totalInstructions) * 10
        ) / 10;

  const founderApprovedCount = instructions.filter(
    (item) => item.founderReview.status === 'Approved'
  ).length;

  const pendingFounderReviewCount = instructions.filter(
    (item) => item.founderReview.status === 'Pending Review'
  ).length;

  const headlessCount = agents.filter(
    (a) => a.laptopDependency === 'Zero (Headless Worker)'
  ).length;
  const headlessAutonomyRate =
    agents.length === 0 ? 100 : Math.round((headlessCount / agents.length) * 100);

  const totalInboxPending = agents.reduce(
    (acc, agent) => acc + agent.inbox.filter((m) => !m.processed).length,
    0
  );
  const totalOutboxDispatched = agents.reduce(
    (acc, agent) => acc + agent.outbox.length,
    0
  );

  const evalPassRate =
    evals.length === 0
      ? 100
      : Math.round((evals.filter((e) => e.passed).length / evals.length) * 1000) / 10;

  return {
    totalInstructions,
    averageYieldPercent,
    founderApprovedCount,
    pendingFounderReviewCount,
    headlessAutonomyRate,
    totalInboxPending,
    totalOutboxDispatched,
    evalPassRate,
  };
}

