/**
 * Pure Super-Synthesis function that reconciles Private Inbox/Outbox state, Build History post-mortems,
 * and Engineer Transition steps into a single Congruent Spine report.
 */
export function synthesizeInboxAndBuildHistory(
  agents: SpecialistAgent[],
  instructions: InstructionRecord[],
  incidents: BuildHistoryIncident[],
  transitionSteps: EngineerTransitionStep[]
): SuperSynthesisReport {
  const neutralizedIncidents = incidents.filter(
    (inc) => inc.status === 'Neutralized by Guard'
  ).length;
  const totalIncidents = incidents.length;

  const completedTransitionSteps = transitionSteps.filter((s) => s.completed).length;
  const totalTransitionSteps = transitionSteps.length;

  const unconsumedInboxEvents = agents.reduce(
    (sum, a) => sum + a.inbox.filter((m) => !m.processed).length,
    0
  );
  const verifiedOutboxBundles = agents.reduce(
    (sum, a) => sum + a.outbox.filter((o) => o.delivered).length,
    0
  );

  const incidentRatio = totalIncidents === 0 ? 1 : neutralizedIncidents / totalIncidents;
  const transitionRatio =
    totalTransitionSteps === 0 ? 1 : completedTransitionSteps / totalTransitionSteps;
  const inboxClearBonus = unconsumedInboxEvents === 0 ? 1 : Math.max(0.85, 1 - unconsumedInboxEvents * 0.03);

  const rawCongruence = (incidentRatio * 0.45 + transitionRatio * 0.35 + inboxClearBonus * 0.2) * 100;
  const congruencePercent = Math.min(100, Math.round(rawCongruence * 10) / 10);

  const totalMemKeys = agents.reduce((s, a) => s + a.memoryKeys, 0);
  const approvedCount = instructions.filter(
    (i) => i.founderReview.status === 'Approved'
  ).length;
  const replayDeterminismHash = `sha256:gen-${totalMemKeys}k-${verifiedOutboxBundles}o-${approvedCount}a-${completedTransitionSteps}c`;

  let spineHealthStatus: SuperSynthesisReport['spineHealthStatus'];
  if (congruencePercent >= 95 && completedTransitionSteps === totalTransitionSteps) {
    spineHealthStatus = 'Congruent Genesis Spine';
  } else if (congruencePercent >= 80) {
    spineHealthStatus = 'Transition In Progress';
  } else {
    spineHealthStatus = 'Drift Detected';
  }

  const synthesisSummary =
    spineHealthStatus === 'Congruent Genesis Spine'
      ? `All ${totalIncidents} legacy build-history failure modes are neutralized by deterministic protocol guards, all ${totalTransitionSteps} engineer cutover steps are complete, and Private Inbox/Outbox replay is 100% congruent (${replayDeterminismHash}).`
      : `Genesis Spine at ${congruencePercent.toFixed(1)}% congruence: ${neutralizedIncidents}/${totalIncidents} historical failure modes neutralized, ${completedTransitionSteps}/${totalTransitionSteps} engineer cutover steps completed, and ${unconsumedInboxEvents} Private Inbox events awaiting headless consumption.`;

  return {
    congruencePercent,
    neutralizedIncidents,
    totalIncidents,
    completedTransitionSteps,
    totalTransitionSteps,
    unconsumedInboxEvents,
    verifiedOutboxBundles,
    replayDeterminismHash,
    spineHealthStatus,
    synthesisSummary,
  };
}

