/**
 * Pure data-and-metrics-driven calculation of an agent's Degree of Agency.
 * The machine determines agency strictly from live Yield %, Eval Score %, Proof Completeness %,
 * and the Founder's Day-0 configurability thresholds.
 */
export function computeAgentDegreeOfAgency(
  agent: SpecialistAgent,
  agentYieldPercent: number,
  proofCompletenessScore: number,
  config: FounderDayZeroConfig
): AgencyDetermination {
  const compositeScore =
    Math.round(
      (agentYieldPercent * 0.4 + agent.evalScore * 0.4 + proofCompletenessScore * 0.2) * 10
    ) / 10;

  let rawLevel: 0 | 1 | 2 | 3 | 4 = 0;
  let rationale = '';

  if (config.requireSha256ProofDayZero && proofCompletenessScore < config.minProofScoreForExecution) {
    rawLevel = 1;
    rationale = `Restricted to L1 Shadow Advisory: proof completeness (${proofCompletenessScore}%) is below Day-0 threshold (${config.minProofScoreForExecution}%).`;
  } else if (
    agentYieldPercent >= config.minYieldForAutonomousOutbox &&
    agent.evalScore >= config.minEvalForFullAgency &&
    proofCompletenessScore === 100
  ) {
    rawLevel = 4;
    rationale = `Granted L4 Full Zero-Touch: Yield (${agentYieldPercent.toFixed(1)}%) ≥ ${config.minYieldForAutonomousOutbox}% and Eval (${agent.evalScore.toFixed(1)}%) ≥ ${config.minEvalForFullAgency}%.`;
  } else if (
    agentYieldPercent >= config.minYieldForAutonomousOutbox - 3 &&
    agent.evalScore >= config.minEvalForFullAgency - 2
  ) {
    rawLevel = 3;
    rationale = `Granted L3 Autonomous Outbox: meets Outbox reliability metrics (Composite ${compositeScore}%).`;
  } else if (agent.evalScore >= 90 && proofCompletenessScore >= config.minProofScoreForExecution) {
    rawLevel = 2;
    rationale = `Bounded at L2 Execution: Eval (${agent.evalScore.toFixed(1)}%) or Yield (${agentYieldPercent.toFixed(1)}%) below L3/L4 promotion gate.`;
  } else {
    rawLevel = 1;
    rationale = `Held at L1 Shadow Advisory pending OKE/Build carnage replay calibration.`;
  }

  const finalLevel = Math.min(rawLevel, config.maxAgencyCeiling) as 0 | 1 | 2 | 3 | 4;
  if (finalLevel < rawLevel) {
    rationale = `Capped at L${finalLevel} by Founder Day-0 Agency Ceiling override (metrics qualified for L${rawLevel}).`;
  }

  const tierMap: Record<0 | 1 | 2 | 3 | 4, AgencyTier> = {
    0: 'L0 · Manual Gate',
    1: 'L1 · Shadow Advisory',
    2: 'L2 · Bounded Execution',
    3: 'L3 · Autonomous Outbox',
    4: 'L4 · Full Zero-Touch Genesis',
  };

  const actionsMap: Record<0 | 1 | 2 | 3 | 4, string[]> = {
    0: ['Read Inbox Schema Only'],
    1: ['Emit Draft Intent', 'Simulate Proof Diff'],
    2: ['Acquire Claim Lock', 'Run Sandboxed AgentKit', 'Attach Proof Token'],
    3: ['Acquire Claim Lock', 'Run Sandboxed AgentKit', 'Atomic Outbox Flush'],
    4: ['Full Headless Inbox-to-Outbox Execution', 'Auto-Commit Estate Memory Checkpoint', 'Self-Heal OKE Drift'],
  };

  return {
    agentId: agent.id,
    agencyTier: tierMap[finalLevel],
    numericLevel: finalLevel,
    compositeScore,
    machineRationale: rationale,
    allowedAutonomousActions: actionsMap[finalLevel],
    rustCrateBinding: `olat_runtime::agency::Level${finalLevel}<${agent.protocolId.replace(/-/g, '_')}>`,
  };
}

