export function gradeFounderQuizSubmission(
  quiz: FounderAcademyQuizItem,
  selectedOptionIndex: number
): FounderQuizEvaluationResult {
  const safeIdx =
    selectedOptionIndex >= 0 && selectedOptionIndex < quiz.options.length
      ? selectedOptionIndex
      : 0;
  const isCorrect = safeIdx === quiz.correctOptionIndex;

  return {
    quizId: quiz.id,
    selectedOptionIndex: safeIdx,
    isCorrect,
    selectedOptionText: quiz.options[safeIdx],
    correctOptionText: quiz.options[quiz.correctOptionIndex],
    progressiveHint: quiz.progressiveHint,
    detailedAnswerExplanation: quiz.detailedAnswerExplanation,
    estateTieInBluf: quiz.estateTieInBluf,
  };
}

export function computeFounderAcademyMastery(
  quizzes: FounderAcademyQuizItem[],
  selectedAnswersByQuizId: Record<string, number>
): FounderAcademyMasterySummary {
  const trackBreakdown: Record<
    FounderEducationTrackId,
    { answered: number; correct: number; total: number }
  > = {
    TRACK_ESTATE_E2E: { answered: 0, correct: 0, total: 0 },
    TRACK_MACHINE_LEARNING: { answered: 0, correct: 0, total: 0 },
    TRACK_DEEP_LEARNING: { answered: 0, correct: 0, total: 0 },
    TRACK_LLM_TRANSFORMERS: { answered: 0, correct: 0, total: 0 },
  };

  let answeredCount = 0;
  let correctCount = 0;

  for (const q of quizzes) {
    trackBreakdown[q.trackId].total += 1;
    const chosen = selectedAnswersByQuizId[q.id];
    if (typeof chosen === 'number') {
      answeredCount += 1;
      trackBreakdown[q.trackId].answered += 1;
      if (chosen === q.correctOptionIndex) {
        correctCount += 1;
        trackBreakdown[q.trackId].correct += 1;
      }
    }
  }

  const totalQuizzesCount = quizzes.length;
  const masteryScorePercent =
    totalQuizzesCount > 0
      ? Math.round((correctCount / totalQuizzesCount) * 1000) / 10
      : 100;

  const masteryTierLabel =
    masteryScorePercent >= 100
      ? 'EXECUTIVE MASTERY SEALED (100%)'
      : masteryScorePercent >= 75
      ? 'PRINCIPAL ARCHITECT PROFICIENCY'
      : 'ACTIVE CONTINUOUS CALIBRATION';

  return {
    totalQuizzesCount,
    answeredCount,
    correctCount,
    masteryScorePercent,
    masteryTierLabel,
    trackBreakdown,
  };
}

