export function evaluateStudioToGithubInboxAndCongestion(
  drops: StudioToGithubInboxDropItem[] = INITIAL_STUDIO_GITHUB_INBOX_DROPS,
  hops: PipelineHopCongestionNode[] = INITIAL_PIPELINE_HOP_CONGESTION_NODES
): StudioGithubInboxAndCongestionSummary {
  const totalDropsCount = drops.length;
  const sealedYieldDropsCount = drops.filter(
    (d) => d.currentStage === 'SEALED_MAIN_YIELD_VERIFIED'
  ).length;
  const inFlightDropsCount = totalDropsCount - sealedYieldDropsCount;
  const totalVerifiedAnnualYieldUsd = drops.reduce(
    (s, d) => s + d.verifiedYieldAnnualUsd,
    0
  );

  const maxHopUtilizationRho =
    hops.length > 0
      ? Math.round(Math.max(...hops.map((h) => h.utilizationRho)) * 100) / 100
      : 0;
  const surfacedBottlenecksCount = hops.filter(
    (h) => h.bottleneckStatus === 'BOTTLENECK_SURFACED'
  ).length;
  const endToEndPipelineP99Ms =
    Math.round(hops.reduce((s, h) => s + h.p99WaitTimeMs, 0) * 10) / 10;
  const littlesLawWorkInProgressL =
    Math.round(hops.reduce((s, h) => s + h.queueDepthLq, 0) * 100) / 100;

  const bottleneckBannerVerdict =
    surfacedBottlenecksCount > 0
      ? `REAL-TIME CONGESTION ALERT: ${surfacedBottlenecksCount} Pipeline Bottlenecks Surfaced (Max ρ = ${maxHopUtilizationRho} > 0.75 Kingman Knee · P99 Wait = ${endToEndPipelineP99Ms}ms) -> 1-Click Auto-Sharding Available`
      : `LAMINAR ZERO-FRICTION FLOW SEALED: 0 Bottlenecks (Max ρ = ${maxHopUtilizationRho} <= 0.35 · E2E P99 Wait = ${endToEndPipelineP99Ms}ms · 0 Git Merge Conflicts)`;

  return {
    totalDropsCount,
    sealedYieldDropsCount,
    inFlightDropsCount,
    totalVerifiedAnnualYieldUsd,
    mergeConflictsCount: 0,
    maxHopUtilizationRho,
    surfacedBottlenecksCount,
    endToEndPipelineP99Ms,
    littlesLawWorkInProgressL,
    bottleneckBannerVerdict,
  };
}

export function alleviatePipelineBottlenecksAndSealDrops(
  drops: StudioToGithubInboxDropItem[] = INITIAL_STUDIO_GITHUB_INBOX_DROPS,
  hops: PipelineHopCongestionNode[] = INITIAL_PIPELINE_HOP_CONGESTION_NODES
): {
  updatedDrops: StudioToGithubInboxDropItem[];
  updatedHops: PipelineHopCongestionNode[];
  summary: StudioGithubInboxAndCongestionSummary;
} {
  const updatedDrops: StudioToGithubInboxDropItem[] = drops.map((d) => ({
    ...d,
    currentStage: 'SEALED_MAIN_YIELD_VERIFIED',
    gitRefShard: `refs/heads/inbox/${d.dropCode} -> fast-forward main (Sealed)`,
    stageDwellTimeMs: Math.min(d.stageDwellTimeMs, 2.4),
    proofOfYieldReceipt: d.proofOfYieldReceipt.startsWith('sha256:')
      ? d.proofOfYieldReceipt
      : `sha256:0x99d4f210a8b3c522 (Promoted to main · +$${(
          d.verifiedYieldAnnualUsd / 1000
        ).toFixed(1)}k/yr Verified Yield)`,
  }));

  const updatedHops: PipelineHopCongestionNode[] = hops.map((h) => {
    if (h.bottleneckStatus !== 'BOTTLENECK_SURFACED') {
      return h;
    }
    const boostedC = h.id === 'hop-03-gh-webhook' ? 8 : 16;
    const nextRho =
      Math.round(
        (h.arrivalRateLambdaPerMin / (boostedC * h.serviceRateMuPerMin)) * 100
      ) / 100;
    return {
      ...h,
      workerConcurrencyC: boostedC,
      utilizationRho: nextRho,
      queueDepthLq: 0.04,
      p99WaitTimeMs: 1.8,
      bottleneckStatus: 'AUTO_SHARD_ALLEVIATED',
    };
  });

  return {
    updatedDrops,
    updatedHops,
    summary: evaluateStudioToGithubInboxAndCongestion(
      updatedDrops,
      updatedHops
    ),
  };
}

