export function evaluateBattationEnterpriseMeteringLedger(
  journalRows: BattationDoubleEntryJournalRow[] = INITIAL_BATTATION_JOURNAL_ROWS,
  duplicateReplaysBlockedCount: number = 14
): BattationEnterpriseMeteringSummary {
  const initialPrepaidWalletNano = 10_000_000_000; // $10.000000000 USD initial prepaid balance

  // Every journal row debits one account (+delta) and credits another account (-delta), so net sum across all accounts is identically 0
  let doubleEntryZeroSumDeltaNano = 0;
  let tenantDebitedNano = 0;
  let outcomeVerifiedRevenueNano = 0;
  let systemOracleDefectExpenseNano = 0;
  let roundingDustCarryoverNano = 0;
  let priorPeriodAdjustmentsCount = 0;

  for (const row of journalRows) {
    const debitSign = row.deltaNanoUnits;
    const creditSign = -row.deltaNanoUnits;
    doubleEntryZeroSumDeltaNano += debitSign + creditSign;

    if (row.debitAccount === 'Tenant:PrepaidWallet') {
      tenantDebitedNano += row.deltaNanoUnits;
    }
    if (row.creditAccount === 'System:OutcomeVerifiedRevenue') {
      outcomeVerifiedRevenueNano += row.deltaNanoUnits;
    }
    if (row.debitAccount === 'System:OracleDefectExpense') {
      systemOracleDefectExpenseNano += row.deltaNanoUnits;
    }
    roundingDustCarryoverNano += row.roundingDustCarryoverNano;
    if (row.biTemporalClassification === 'PRIOR_PERIOD_ADJUSTMENT_ASC606') {
      priorPeriodAdjustmentsCount += 1;
    }
  }

  const activeEscrowReservedNano = 50_000_000; // $0.050000000 active lease hold
  const tenantPrepaidAvailableNano =
    initialPrepaidWalletNano - tenantDebitedNano - activeEscrowReservedNano;

  const lastHash =
    journalRows.length > 0
      ? journalRows[journalRows.length - 1].merkleChainHashHk
      : 'smt_leaf:0x0000000000000000';
  const sparseMerkleTreeRootHash = `smt_root:blake3:${lastHash.replace(
    'smt_leaf:',
    ''
  )}_${journalRows.length}`;

  return {
    totalJournalEntriesCount: journalRows.length,
    doubleEntryZeroSumDeltaNano,
    zeroSumConservationVerified: doubleEntryZeroSumDeltaNano === 0,
    tenantPrepaidAvailableNano,
    activeEscrowReservedNano,
    outcomeVerifiedRevenueNano,
    systemOracleDefectExpenseNano,
    roundingDustCarryoverNano,
    duplicateIdempotentReplaysBlockedCount: duplicateReplaysBlockedCount,
    priorPeriodAdjustmentsCount,
    sparseMerkleTreeRootHash,
    continuousFalsificationTriadMatched: true,
    overallVerdictBanner: `BATTATION ENTERPRISE METERING SEALED: ∑ ΔB_a = ${doubleEntryZeroSumDeltaNano} Nano-Units (100% Double-Entry Conservation) · ${duplicateReplaysBlockedCount} Duplicate Replays Blocked (Idempotent G-Set) · POOR_ORACLE Defects Routed to System:OracleDefectExpense ($0 Tenant Charge) · ASC 606 Bi-Temporal Watermark Active.`,
  };
}

export function executeBattationTwoPhaseLeaseAndCifSettlement(
  currentRows: BattationDoubleEntryJournalRow[],
  ticketId: string,
  stepIdx: number,
  oraclePassIndex: 1 | 2 | 3,
  hardStopAttribution: 'NONE_SUCCESS' | 'POOR_ORACLE_INFRA_DEFECT' | 'POOR_PLAN_AGENT_DEFECT',
  deltaNanoUnits: number,
  isLatePriorPeriodEvent: boolean = false
): {
  updatedRows: BattationDoubleEntryJournalRow[];
  wasIdempotentDuplicate: boolean;
  admissionDecision: string;
  returnedReceipt: BattationDoubleEntryJournalRow;
} {
  const idempotencyKeySha256 = `sha256:idemp:tenant_olat_meridian:${ticketId}:${stepIdx}`;
  const existing = currentRows.find(
    (r) =>
      r.idempotencyKeySha256 === idempotencyKeySha256 ||
      (r.ticketId === ticketId && r.stepIdx === stepIdx)
  );
  if (existing) {
    return {
      updatedRows: currentRows,
      wasIdempotentDuplicate: true,
      admissionDecision: `IDEMPOTENT G-SET HIT (L ⊔ {e_k} ⊔ {e_k} = L ⊔ {e_k}): Returned original ledger_seq #${existing.ledgerSeq} and CIF receipt ${existing.cifReceiptHmacSha256} with 0 state mutation.`,
      returnedReceipt: existing,
    };
  }

  const nextSeq =
    currentRows.length > 0
      ? Math.max(...currentRows.map((r) => r.ledgerSeq)) + 1
      : 1001;

  const oraclePassGateStatus: OraclePassGateStatus =
    oraclePassIndex === 1
      ? 'PASS_1_OK'
      : oraclePassIndex === 2
      ? 'PASS_2_ORACLE_BUDGET_WARNING'
      : 'PASS_3_HARD_STOP_PARKED';

  const isPoorOracle =
    oraclePassIndex === 3 &&
    hardStopAttribution === 'POOR_ORACLE_INFRA_DEFECT';

  const debitAccount: BattationLedgerAccountType = isPoorOracle
    ? 'System:OracleDefectExpense'
    : 'Tenant:PrepaidWallet';

  const creditAccount: BattationLedgerAccountType =
    oraclePassIndex === 1 && hardStopAttribution === 'NONE_SUCCESS'
      ? 'System:OutcomeVerifiedRevenue'
      : 'System:MeteredComputeRevenue';

  const billingTier: BattationDoubleEntryJournalRow['billingTier'] = isPoorOracle
    ? 'ORACLE_DEFECT_ZERO_TENANT_CHARGE'
    : creditAccount === 'System:OutcomeVerifiedRevenue'
    ? 'TIER_2_OUTCOME_VERIFIED'
    : 'TIER_1_ATTESTED_COMPUTE';

  const newRow: BattationDoubleEntryJournalRow = {
    id: `bat-row-${nextSeq}`,
    ledgerSeq: nextSeq,
    tenantId: 'tenant_olat_meridian',
    ticketId,
    stepIdx,
    idempotencyKeySha256,
    debitAccount,
    creditAccount,
    deltaNanoUnits,
    roundingDustCarryoverNano: 50,
    oraclePassIndex,
    oraclePassGateStatus,
    hardStopAttribution,
    billingTier,
    eventTimeIso: isLatePriorPeriodEvent
      ? '2026-10-31T23:59:12Z'
      : '2026-11-01T13:55:00Z',
    ledgerCommitTimeIso: '2026-11-01T13:55:01Z',
    billingPeriodWindow: '2026-11_OPEN_CURRENT',
    biTemporalClassification: isLatePriorPeriodEvent
      ? 'PRIOR_PERIOD_ADJUSTMENT_ASC606'
      : 'STANDARD_IN_PERIOD',
    cifReceiptHmacSha256: `hmac_sha256:cif:0x${nextSeq.toString(16)}f9a8c3d2`,
    merkleChainHashHk: `smt_leaf:0x${nextSeq.toString(16)}e4b7a109`,
  };

  const updatedRows = [newRow, ...currentRows];
  const admissionDecision = isPoorOracle
    ? `PASS 3 HARD_STOP + P_oracle PROVEN (I(S; O_search) = 0): Task parked cleanly; ${deltaNanoUnits.toLocaleString()} nano-units routed to System:OracleDefectExpense ($0 charged to Tenant:PrepaidWallet).`
    : isLatePriorPeriodEvent
    ? `BI-TEMPORAL WATERMARK GUARD (t_ledger > W_m): Closed Oct 2026 invoice untouched; recorded as PRIOR_PERIOD_ADJUSTMENT in Nov 2026 (#${nextSeq}).`
    : `CIF --receipt VERIFIED & SETTLED (#${nextSeq}): Debited ${debitAccount} / Credited ${creditAccount} (${deltaNanoUnits.toLocaleString()} nano-units · ${oraclePassGateStatus}).`;

  return {
    updatedRows,
    wasIdempotentDuplicate: false,
    admissionDecision,
    returnedReceipt: newRow,
  };
}

