export function evaluateSinglePassMultiFaultDagAndTruthProtocol(
  classScans: BoundedFaultClassScanEntry[] = INITIAL_BOUNDED_FAULT_CLASS_SCANS,
  faultTickets: FaultGraphNodeAndTicketRecord[] = INITIAL_FAULT_GRAPH_NODES_AND_TICKETS,
  truthClaims: EpistemicTruthClaimRecord[] = INITIAL_TRUTH_CLAIM_LEDGER_RECORDS
): SinglePassMultiFaultDagAndTruthSummary {
  const totalFaultClassesCount = classScans.length;
  const scannedFaultClassesCount = classScans.filter(
    (c) => c.scanned && c.evidenceRef.trim().length > 0
  ).length;
  const unscannedClassesCount =
    totalFaultClassesCount - scannedFaultClassesCount;

  const totalFaultNodesAndTicketsCount = faultTickets.length;
  const fixNowSafeTopologicalCount = faultTickets.filter(
    (t) =>
      t.disposition === 'fix-now' &&
      t.safetyPredicate.result === 'safe' &&
      t.safetyPredicate.failedChecks.length === 0
  ).length;
  const escalatedOrBlockedUnsafeCount = faultTickets.filter(
    (t) =>
      t.safetyPredicate.result === 'unsafe' &&
      (t.disposition === 'escalate' || t.disposition === 'block')
  ).length;
  const untriagedTicketTheaterCount = faultTickets.filter(
    (t) =>
      t.evidenceRefs.length === 0 ||
      !t.ownerSpecialistId ||
      t.ttlMinutes <= 0
  ).length;

  const admittedClaims = truthClaims.filter(
    (c) => c.claimCategory !== 'HALLUCINATION_BLOCKED_AT_GATE'
  );
  const meanEpistemicConfidenceScorePercent =
    admittedClaims.length > 0
      ? Math.round(
          (admittedClaims.reduce(
            (acc, c) => acc + c.computedConfidenceScorePercent,
            0
          ) /
            admittedClaims.length) *
            10
        ) / 10
      : 100.0;

  const hallucinationsInterceptedAndBlockedCount = truthClaims.filter(
    (c) => c.claimCategory === 'HALLUCINATION_BLOCKED_AT_GATE'
  ).length;

  const unprovenClaimsLeakedToFounderCount = truthClaims.filter(
    (c) =>
      c.claimCategory === 'FACT_VERIFIED_WITH_PROOF' &&
      (c.computedConfidenceScorePercent < 95.0 ||
        c.proofOfClaimReceipts.length === 0)
  ).length;

  return {
    totalFaultClassesCount,
    scannedFaultClassesCount,
    unscannedClassesCount,
    totalFaultNodesAndTicketsCount,
    fixNowSafeTopologicalCount,
    escalatedOrBlockedUnsafeCount,
    untriagedTicketTheaterCount,
    meanEpistemicConfidenceScorePercent,
    hallucinationsInterceptedAndBlockedCount,
    unprovenClaimsLeakedToFounderCount,
    totalPassesExecutedForFullIncident: 2, // P1 Snapshot + P2/P4 Deterministic Classify & Topological Fix (0 Model Passes)
    executiveDagAndTruthBluf: `SINGLE-PASS MULTI-FAULT DAG & TRUTH PROTOCOL SEALED: ${scannedFaultClassesCount}/${totalFaultClassesCount} Fault Classes Scanned in 1 Snapshot · ${fixNowSafeTopologicalCount} Safe Nodes Remediated in Topological Order (Wave 0 Unmask -> Wave 1 Safe Roots) · ${escalatedOrBlockedUnsafeCount} Unsafe Nodes Blocked & Ticketed with TTL · ${unprovenClaimsLeakedToFounderCount} Unproven Claims Leaked (${hallucinationsInterceptedAndBlockedCount} Hallucinations Blocked at Gate).`,
  };
}

export function executeSinglePassMultiFaultDagAndTruthVerification(
  candidateClaimToFounder: string,
  attachedEvidenceRefs: string[],
  scannedClassesCount: number = 11,
  unresolvedGraphNodesCount: number = 0,
  currentTruthClaims: EpistemicTruthClaimRecord[] = INITIAL_TRUTH_CLAIM_LEDGER_RECORDS
): {
  computedConfidenceScorePercent: number;
  claimClassification: EpistemicTruthClaimRecord['claimCategory'];
  admittedToFounderSurface: boolean;
  wave0UnmaskExecutedOrder: string[];
  wave1SafeRootRemediationOrder: string[];
  escalatedUnsafeTicketIds: string[];
  newTruthClaimRecord: EpistemicTruthClaimRecord;
  updatedTruthClaims: EpistemicTruthClaimRecord[];
  updatedSummary: SinglePassMultiFaultDagAndTruthSummary;
  verificationBluf: string;
} {
  const safeScanned = Math.min(11, Math.max(0, scannedClassesCount));
  const classCoverageRatio = safeScanned / 11;
  const requiredEvidenceCount = 2;
  const evidenceRatio = Math.min(
    1.0,
    attachedEvidenceRefs.filter((r) => r.trim().length > 0).length /
      requiredEvidenceCount
  );
  const graphResolutionRatio = Math.max(
    0,
    1 - Math.min(7, Math.max(0, unresolvedGraphNodesCount)) / 7
  );
  const hasValidReceiptSignature = attachedEvidenceRefs.some(
    (r) =>
      r.includes('snap:') ||
      r.includes('sha256:') ||
      r.includes('blake3:') ||
      r.includes('verify_')
  );

  const rawConfidence =
    classCoverageRatio *
    evidenceRatio *
    graphResolutionRatio *
    (hasValidReceiptSignature ? 100.0 : 0.0);
  const computedConfidenceScorePercent = Math.round(rawConfidence * 10) / 10;

  let claimClassification: EpistemicTruthClaimRecord['claimCategory'];
  let admittedToFounderSurface: boolean;
  let truthGateActionTaken: string;

  if (computedConfidenceScorePercent >= 95.0) {
    claimClassification = 'FACT_VERIFIED_WITH_PROOF';
    admittedToFounderSurface = true;
    truthGateActionTaken = `ADMITTED AS VERIFIED FACT (Confidence = ${computedConfidenceScorePercent}% >= 95.0% floor · ${attachedEvidenceRefs.length} signed evidence refs verified).`;
  } else if (
    computedConfidenceScorePercent >= 70.0 &&
    hasValidReceiptSignature
  ) {
    claimClassification = 'HYPOTHESIS_EXPLICITLY_BOUNDED';
    admittedToFounderSurface = true;
    truthGateActionTaken = `ADMITTED ONLY AS BOUNDED HYPOTHESIS (Confidence = ${computedConfidenceScorePercent}% · Discloses ${unresolvedGraphNodesCount} unresolved node(s) and ${11 - safeScanned} unscanned class(es)).`;
  } else {
    claimClassification = 'HALLUCINATION_BLOCKED_AT_GATE';
    admittedToFounderSurface = false;
    truthGateActionTaken = `HARD-BLOCKED AT TRUTH GATE (Confidence = ${computedConfidenceScorePercent}% < 95.0% · Unproven claim intercepted before reaching Founder).`;
  }

  const wave0UnmaskExecutedOrder = INITIAL_FAULT_GRAPH_NODES_AND_TICKETS.filter(
    (t) => t.topologicalFixWave === 'WAVE_0_UNMASK_ENABLES'
  ).map((t) => `${t.ticketId} (${t.faultId}: ${t.faultTitle})`);

  const wave1SafeRootRemediationOrder =
    INITIAL_FAULT_GRAPH_NODES_AND_TICKETS.filter(
      (t) => t.topologicalFixWave === 'WAVE_1_SAFE_ROOTS'
    ).map((t) => `${t.ticketId} (${t.faultId}: ${t.faultTitle})`);

  const escalatedUnsafeTicketIds = INITIAL_FAULT_GRAPH_NODES_AND_TICKETS.filter(
    (t) => t.topologicalFixWave === 'TICKETED_ESCALATED_HOLD'
  ).map((t) => `${t.ticketId} (${t.faultId} -> ${t.disposition.toUpperCase()})`);

  const nextIdNum = currentTruthClaims.length + 1;
  const newTruthClaimRecord: EpistemicTruthClaimRecord = {
    claimId: `TRUTH-CLM-0${nextIdNum}`,
    statementToFounder: candidateClaimToFounder,
    claimCategory: claimClassification,
    scannedClassesCount: safeScanned,
    totalFaultClassesCount: 11,
    verifiedEvidenceCount: attachedEvidenceRefs.length,
    requiredEvidenceCount,
    unresolvedGraphNodesCount,
    totalGraphNodesCount: 7,
    computedConfidenceScorePercent,
    proofOfClaimReceipts: attachedEvidenceRefs,
    truthGateActionTaken,
  };

  const updatedTruthClaims = [newTruthClaimRecord, ...currentTruthClaims];
  const updatedSummary = evaluateSinglePassMultiFaultDagAndTruthProtocol(
    INITIAL_BOUNDED_FAULT_CLASS_SCANS,
    INITIAL_FAULT_GRAPH_NODES_AND_TICKETS,
    updatedTruthClaims
  );

  const verificationBluf = admittedToFounderSurface
    ? `PROOF-OF-CLAIM VERIFIED (${claimClassification} · Confidence = ${computedConfidenceScorePercent}%): Wave 0 unmasked 3 \`enables\` guards (\`2>/dev/null\`, \`trajectory_lock.py\`, \`epistemic_firewall.py\`), Wave 1 remediated 2 safe roots (\`FLT-06\` \`pi\` \`SIGTSTP\` + \`FLT-05\` \`zsh\` \`#\`), and held 2 unsafe nodes (\`FLT-01\`, \`FLT-07\`) in escalated tickets.`
    : `HALLUCINATION INTERCEPTED & BLOCKED (Confidence = ${computedConfidenceScorePercent}% < 95.0%): Statement "${candidateClaimToFounder.slice(0, 68)}..." lacked cryptographic proof receipts or full class coverage and was blocked from the Founder surface.`;

  return {
    computedConfidenceScorePercent,
    claimClassification,
    admittedToFounderSurface,
    wave0UnmaskExecutedOrder,
    wave1SafeRootRemediationOrder,
    escalatedUnsafeTicketIds,
    newTruthClaimRecord,
    updatedTruthClaims,
    updatedSummary,
    verificationBluf,
  };
}

