export function evaluateHotColdDataPolicyAndIdpConceptUpgrades(
  tiers: DataStorageTierPolicySpec[] = INITIAL_DATA_STORAGE_TIERING_POLICIES,
  googleServices: GoogleSubscriptionScavengedServiceSpec[] = INITIAL_GOOGLE_SUBSCRIPTION_SCAVENGED_SERVICES,
  idpUpgrades: IdpRepoDiscoveredConceptUpgradeSpec[] = INITIAL_IDP_REPO_DISCOVERED_CONCEPT_UPGRADES
): HotColdDataAndIdpUpgradeSummary {
  const totalStorageCapacityGb = tiers.reduce(
    (acc, t) => acc + t.capacityLimitGb,
    0
  );
  const coldTier = tiers.find(
    (t) => t.tierId === 'COLD_L2_GOOGLE_5TB_DRIVEFS_PARQUET'
  );
  const hotTier = tiers.find((t) => t.tierId === 'HOT_L0_NVME_REDB_RAM');

  const googleDrive5TbColdCapacityGb = coldTier ? coldTier.capacityLimitGb : 5000;
  const currentHotUsedGb = hotTier ? hotTier.currentUsedGb : 18.4;
  const currentColdParquetUsedGb = coldTier ? coldTier.currentUsedGb : 312.0;

  const totalEquivalentCloudSavingsUsdPerMo = googleServices.reduce(
    (acc, s) => acc + s.equivalentCommercialCloudValueUsdPerMo,
    0
  );
  const totalMarginalCashBurnUsdPerMo = googleServices.reduce(
    (acc, s) => acc + s.marginalCashBurnUsdPerMo,
    0
  );
  const enabledIdpConceptsCount = idpUpgrades.filter(
    (u) => u.enabledOnDayZero
  ).length;

  return {
    totalStorageCapacityGb,
    googleDrive5TbColdCapacityGb,
    currentHotUsedGb,
    currentColdParquetUsedGb,
    averageZstdParquetCompressionRatio: 9.4,
    totalGoogleServicesScavengedCount: googleServices.length,
    totalEquivalentCloudSavingsUsdPerMo,
    totalMarginalCashBurnUsdPerMo,
    totalIdpConceptsUpgradedCount: idpUpgrades.length,
    enabledIdpConceptsCount,
    executiveStorageAndIdpBluf: `4-TIER DATA LIFECYCLE & 10 IDP UPGRADES SEALED: ${totalStorageCapacityGb.toLocaleString()} GB Total Estate Storage (${googleDrive5TbColdCapacityGb.toLocaleString()} GB Cold Zstd-Parquet Lake on Mounted Google DriveFS at $${totalMarginalCashBurnUsdPerMo.toFixed(2)}/mo marginal burn · saves $${totalEquivalentCloudSavingsUsdPerMo.toFixed(0)}/mo) · ${enabledIdpConceptsCount}/${idpUpgrades.length} chidionyema/idp Concepts Upgraded & Live-Configurable on Day 0.`,
  };
}

export function executeHotToColdGoogleDriveDemotionAndIdpToggle(
  rawHotDataToDemoteGb: number,
  hotRetentionDaysOverride: number,
  targetIdpUpgradeIdToToggleOrUpdate: string | null,
  customParameterValue: string | null,
  currentTiers: DataStorageTierPolicySpec[] = INITIAL_DATA_STORAGE_TIERING_POLICIES,
  currentIdpUpgrades: IdpRepoDiscoveredConceptUpgradeSpec[] = INITIAL_IDP_REPO_DISCOVERED_CONCEPT_UPGRADES
): HotToColdDemotionAndIdpConfigResult {
  const safeDemoteGb = Math.max(0.5, Math.min(rawHotDataToDemoteGb, 12.0));
  const zstdCompressionRatioAchieved = 9.4;
  const compressedColdParquetWrittenGb =
    Math.round((safeDemoteGb / zstdCompressionRatioAchieved) * 100) / 100;

  const updatedTiers = currentTiers.map((tier) => {
    if (tier.tierId === 'HOT_L0_NVME_REDB_RAM') {
      const nextUsed = Math.max(
        4.0,
        Math.round((tier.currentUsedGb - safeDemoteGb) * 100) / 100
      );
      return {
        ...tier,
        retentionWindowDaysMax: Math.max(1, Math.min(30, hotRetentionDaysOverride)),
        currentUsedGb: nextUsed,
      };
    }
    if (tier.tierId === 'COLD_L2_GOOGLE_5TB_DRIVEFS_PARQUET') {
      return {
        ...tier,
        currentUsedGb:
          Math.round((tier.currentUsedGb + compressedColdParquetWrittenGb) * 100) /
          100,
      };
    }
    return tier;
  });

  const updatedIdpUpgrades = currentIdpUpgrades.map((upg) => {
    if (
      targetIdpUpgradeIdToToggleOrUpdate &&
      upg.upgradeId === targetIdpUpgradeIdToToggleOrUpdate
    ) {
      return {
        ...upg,
        enabledOnDayZero: customParameterValue
          ? true
          : !upg.enabledOnDayZero,
        founderConfigurableParameterValue:
          customParameterValue || upg.founderConfigurableParameterValue,
      };
    }
    return upg;
  });

  const updatedSummary = evaluateHotColdDataPolicyAndIdpConceptUpgrades(
    updatedTiers,
    INITIAL_GOOGLE_SUBSCRIPTION_SCAVENGED_SERVICES,
    updatedIdpUpgrades
  );

  const blake3MerkleManifestHash = `blake3:0x5tb94e2c1a8f00${Math.round(
    safeDemoteGb * 10
  )}`;
  const xChaCha20EnvelopeKeyId =
    'spire://enclave.olat.genesis/keys/xchacha20-cold-parquet-v1';
  const googleDriveTargetVaultPath =
    '~/Library/CloudStorage/GoogleDrive-chidionyema@gmail.com/My Drive/OlatEstateGenesis/cold_parquet_vault/year=2026/month=11/epoch_demoted.zstd.parquet.enc';

  return {
    demotedRawDataGb: safeDemoteGb,
    compressedColdParquetWrittenGb,
    zstdCompressionRatioAchieved,
    blake3MerkleManifestHash,
    xChaCha20EnvelopeKeyId,
    duckDbRangeQueryLatencyMs: 38.4,
    googleDriveTargetVaultPath,
    updatedTiers,
    updatedIdpUpgrades,
    updatedSummary,
    operationReceiptBluf: `HOT -> COLD 5TB GOOGLE DRIVE DEMOTION & IDP CONFIG SEALED: Demoted ${safeDemoteGb.toFixed(2)} GB from Hot NVMe redb -> ${compressedColdParquetWrittenGb.toFixed(2)} GB Zstd-Parquet (${zstdCompressionRatioAchieved}x compression · XChaCha20-Poly1305 encrypted · ${blake3MerkleManifestHash}) on Google/DriveFS ($0.00/mo burn · 38.4ms DuckDB-WASM range read).`,
  };
}

