export function evaluateDayZeroAgentHaAndNonBlockingExecution(
  fleetHa: AgentHighAvailabilityResponsivenessRecord[] = INITIAL_AGENT_HA_RESPONSIVENESS_FLEET,
  bgTasks: BackgroundTaskSupervisorRecord[] = INITIAL_BACKGROUND_TASK_SUPERVISOR_LEDGER,
  principles: NonBlockingExecutionPrincipleSpec[] = INITIAL_NON_BLOCKING_EXECUTION_PRINCIPLES
): DayZeroAgentHaAndNonBlockingSummary {
  const totalMonitoredAgentsCount = fleetHa.length;
  const fleetFounderAvailabilityPercent =
    totalMonitoredAgentsCount > 0
      ? Math.round(
          (fleetHa.reduce((acc, a) => acc + a.founderAvailabilityPercent, 0) /
            totalMonitoredAgentsCount) *
            10
        ) / 10
      : 100.0;

  const maxFleetControlPlanePingMs = fleetHa.reduce(
    (max, a) => Math.max(max, a.controlPlaneP99PingMs),
    0
  );
  const meanFleetControlPlanePingMs =
    totalMonitoredAgentsCount > 0
      ? Math.round(
          (fleetHa.reduce((acc, a) => acc + a.controlPlaneP99PingMs, 0) /
            totalMonitoredAgentsCount) *
            100
        ) / 100
      : 3.0;

  const totalHeadOfLineBlockingMs =
    fleetHa.reduce((acc, a) => acc + a.headOfLineBlockingMs, 0) +
    bgTasks.reduce((acc, t) => acc + t.holBlockingAddedMs, 0);

  const totalBlockingCommandsInterceptedCount = fleetHa.reduce(
    (acc, a) => acc + a.blockingCommandsInterceptedCount,
    0
  );

  const activeBackgroundDaemonsAndTasksCount = bgTasks.filter(
    (t) =>
      t.lifecycleState === 'RUNNING_BACKGROUND_STREAMING' ||
      t.lifecycleState === 'DAEMON_SUPERVISED_ACTIVE'
  ).length;

  const preemptedStdinOrZombieTrapsCount = bgTasks.filter(
    (t) => t.lifecycleState === 'PREEMPTED_STDIN_TRAP_BLOCKED'
  ).length;

  return {
    totalMonitoredAgentsCount,
    fleetFounderAvailabilityPercent,
    maxFleetControlPlanePingMs,
    meanFleetControlPlanePingMs,
    totalHeadOfLineBlockingMs,
    totalBlockingCommandsInterceptedCount,
    totalBackgroundTasksSupervisedCount: bgTasks.length,
    activeBackgroundDaemonsAndTasksCount,
    preemptedStdinOrZombieTrapsCount,
    busyWaitPollingLoopsPermittedCount: 0,
    haExecutiveVerdictBluf: `DAY-0 AGENT HIGH-AVAILABILITY & NON-BLOCKING KERNEL SEALED (${principles.length}/6 HA-ASYNC Rules): ${totalMonitoredAgentsCount}/${totalMonitoredAgentsCount} Agents at ${fleetFounderAvailabilityPercent}% Founder Availability · Mean Control-Plane Ping ${meanFleetControlPlanePingMs}ms (Max ${maxFleetControlPlanePingMs}ms <= 12.0ms SLA) · ${totalHeadOfLineBlockingMs.toFixed(2)}ms Head-of-Line Blocking · ${totalBlockingCommandsInterceptedCount} Blocking Commands Auto-Backgrounded (${bgTasks.length} Supervised Tasks, ${preemptedStdinOrZombieTrapsCount} stdin Traps Preempted, 0 Polling Loops).`,
  };
}

export function interceptCommandAndVerifyFounderResponsiveness(
  targetAgentCode: string,
  submittedCommandInput: string,
  concurrentFounderDirectiveInput: string,
  simulateStdinHangTrap: boolean,
  currentTasks: BackgroundTaskSupervisorRecord[] = INITIAL_BACKGROUND_TASK_SUPERVISOR_LEDGER,
  currentFleetHa: AgentHighAvailabilityResponsivenessRecord[] = INITIAL_AGENT_HA_RESPONSIVENESS_FLEET
): InterceptCommandAndFounderPingResult {
  const cleanCmd =
    submittedCommandInput.trim().length > 0
      ? submittedCommandInput.trim()
      : 'cargo build --release --workspace && npx --yes tsx --test src/lib/protocolEngine.test.ts';
  const cleanDirective =
    concurrentFounderDirectiveInput.trim().length > 0
      ? concurrentFounderDirectiveInput.trim()
      : 'Founder Instant Ping: Report live Meridian CPI yield delta & rebalance status right now.';

  const nextIdx = currentTasks.length + 1;
  const taskCode = `BG-TASK-0${nextIdx}`;
  const lowerCmd = cleanCmd.toLowerCase();
  const isDaemonCmd =
    lowerCmd.includes('--watch') ||
    lowerCmd.includes('server.ts') ||
    lowerCmd.includes('vite') ||
    lowerCmd.includes('daemon') ||
    lowerCmd.includes('tail -f');

  const matchedAgent =
    currentFleetHa.find((a) => a.agentCode === targetAgentCode) ||
    currentFleetHa[0];

  const lifecycleState: BackgroundTaskLifecycleState = simulateStdinHangTrap
    ? 'PREEMPTED_STDIN_TRAP_BLOCKED'
    : isDaemonCmd
      ? 'DAEMON_SUPERVISED_ACTIVE'
      : 'RUNNING_BACKGROUND_STREAMING';

  const interceptedTask: BackgroundTaskSupervisorRecord = {
    taskId: `bg-task-0${nextIdx}`,
    taskCode,
    assignedAgentCode: matchedAgent.agentCode,
    rawCommandSubmitted: cleanCmd,
    interceptionReason: simulateStdinHangTrap
      ? 'HA-ASYNC-04 Guard: Detected interactive `stdin` prompt / TTY hang attempt; preempted pgid in 3.5ms'
      : isDaemonCmd
        ? 'HA-ASYNC-05 Guard: Detected long-running daemon/watcher; promoted to `IsDaemon: true` background lease'
        : 'HA-ASYNC-02 Guard: Estimated execution > 50ms sync ceiling; auto-promoted to detached background worker',
    rewrittenNonBlockingDispatch: simulateStdinHangTrap
      ? `async_bg::preempt_pgid("${cleanCmd.slice(0, 42)}...", signal=SIGKILL, stdin=/dev/null, latency=3.5ms)`
      : `async_bg::spawn_detached("${cleanCmd.slice(0, 42)}...", wait_ms=50, is_daemon=${isDaemonCmd}, cgroup_weight=20, notify=pidfd_redb)`,
    isDaemon: isDaemonCmd && !simulateStdinHangTrap,
    spawnLatencyMs: 1.5,
    founderPingDuringTaskMs: matchedAgent.controlPlaneP99PingMs,
    holBlockingAddedMs: 0.0,
    lifecycleState,
    cifTaskReceipt: `cif_bgtask:0${nextIdx}:hmac_sha256:0x99d1e4a00${nextIdx}`,
  };

  const updatedBackgroundTasks = [interceptedTask, ...currentTasks];
  const updatedAgentFleetHa = currentFleetHa.map((ag) =>
    ag.agentCode === matchedAgent.agentCode
      ? {
          ...ag,
          blockingCommandsInterceptedCount:
            ag.blockingCommandsInterceptedCount + 1,
          activeBackgroundTasksCount: simulateStdinHangTrap
            ? ag.activeBackgroundTasksCount
            : ag.activeBackgroundTasksCount + 1,
          headOfLineBlockingMs: 0.0,
          founderAvailabilityPercent: 100.0,
        }
      : ag
  );

  const updatedSummary = evaluateDayZeroAgentHaAndNonBlockingExecution(
    updatedAgentFleetHa,
    updatedBackgroundTasks,
    INITIAL_NON_BLOCKING_EXECUTION_PRINCIPLES
  );

  const interceptionAuditBluf = simulateStdinHangTrap
    ? `HA-ASYNC-04 STDIN HANG TRAP PREEMPTED IN 3.5ms (${taskCode} on ${matchedAgent.agentCode}): Intercepted interactive prompt in "${cleanCmd.slice(0, 56)}" via </dev/null contract · Answered concurrent Founder directive "${cleanDirective.slice(0, 48)}" simultaneously in ${matchedAgent.controlPlaneP99PingMs}ms (0.00ms HoL block).`
    : `HA-ASYNC-02 BLOCKING COMMAND AUTO-BACKGROUNDED IN 1.5ms (${taskCode} on ${matchedAgent.agentCode}): Promoted "${cleanCmd.slice(0, 56)}" to detached cgroup worker (isDaemon=${isDaemonCmd && !simulateStdinHangTrap}) · Answered concurrent Founder directive "${cleanDirective.slice(0, 48)}" simultaneously in ${matchedAgent.controlPlaneP99PingMs}ms (0.00ms HoL block · 100.0% Founder Availability).`;

  return {
    interceptedTask,
    updatedBackgroundTasks,
    updatedAgentFleetHa,
    concurrentFounderDirectiveText: cleanDirective,
    concurrentFounderResponseLatencyMs: matchedAgent.controlPlaneP99PingMs,
    holBlockingInducedMs: 0,
    wasStdinHangPreempted: simulateStdinHangTrap,
    interceptionAuditBluf,
    updatedSummary,
  };
}

