export function executeLawEnforcerAndCounterfactualFalsifierDrill(
  targetLawId: ConstitutionalLawId,
  mode: 'CLEAN_CANONICAL_STATE' | 'INJECT_COUNTERFACTUAL_MUTATION_FALSIFIER',
  laws: ConstitutionalLawEnforcerAndFalsifierSpec[] = INITIAL_CONSTITUTIONAL_LAWS_I1_TO_I8_SPECS
): LawFalsifierDrillExecutionResult {
  const selectedLaw =
    laws.find((l) => l.lawId === targetLawId) || laws[0];

  const isMutationDrill = mode === 'INJECT_COUNTERFACTUAL_MUTATION_FALSIFIER';
  const enforcerExitCode: 0 | 1 = isMutationDrill ? 1 : 0;

  const drillAuditBluf = isMutationDrill
    ? `COUNTERFACTUAL FALSIFIER PROVEN REAL (${selectedLaw.counterfactualFalsifierId} on Law ${selectedLaw.lawId}): Injected "${selectedLaw.counterfactualMutationStimulus}" into ${selectedLaw.genesisRealEnforcerFilePath} -> Enforcer deterministically returned exit code 1 (REJECTED_NONZERO_PROVEN_NOT_FABRICATED). Zero fabricated passes possible.`
    : `OUT-OF-PROCESS ENFORCER VERIFIED (${selectedLaw.lawId} via ${selectedLaw.genesisRealEnforcerFilePath}): Physical enforcer file verified on disk; invariant "${selectedLaw.mathematicalInvariant}" holds with independent artifact digest ${selectedLaw.outOfProcessArtifactSha256} (exit code 0).`;

  return {
    selectedLaw,
    modeTested: mode,
    enforcerExitCode,
    wasMutationFalsifierCaughtAndRejected: isMutationDrill,
    outOfProcessVerifierDigest: selectedLaw.outOfProcessArtifactSha256,
    drillAuditBluf,
  };
}

