export const MIN_ASYMMETRY_RATIO = 10.0;
export const FOUNDER_FRICTION_PENALTY_WEIGHT = 1000000.0;

export type ExecutionPhase = 'PreFlightAnticipatory' | 'InFlightDynamicIntervention';

export type EnforcementMechanism =
  | 'AdHocPointFix'
  | 'CompileTimeTypeGate'
  | 'BootTimeDayZeroGate'
  | 'OracleShieldPass0Gate'
  | 'CiPreMergeRegressionGate';

export interface AsymmetricProposal {
  proposal_id: string;
  phase: ExecutionPhase;
  specific_symptom: string;
  problem_equivalence_class: string;
  class_cardinality_estimate: number;
  expected_probes_saved_per_instance: number;
  implementation_probe_cost: number;
  founder_friction_cost: number;
  constraint_dissolved?: string;
  hard_invariants_preserved: boolean;
  wwfd_alignment_score: number;
  enforcement_mechanism: EnforcementMechanism;
  structural_remediation_cmd: string;
}

export interface AsymmetryEvaluationReceipt {
  proposal_id: string;
  approved: boolean;
  computed_asymmetry_ratio: number;
  recurrence_probability: number;
  verdict_reason: string;
  permanent_dna_uri: string;
}

export function getEnforcementRecurrenceProb(mech: EnforcementMechanism): number {
  switch (mech) {
    case 'AdHocPointFix':
      return 0.85;
    case 'CompileTimeTypeGate':
    case 'BootTimeDayZeroGate':
    case 'OracleShieldPass0Gate':
    case 'CiPreMergeRegressionGate':
      return 0.0;
  }
}

export function evaluateAndEnforceAsymmetry(
  proposal: AsymmetricProposal
): AsymmetryEvaluationReceipt {
  if (!proposal.hard_invariants_preserved) {
    return {
      proposal_id: proposal.proposal_id,
      approved: false,
      computed_asymmetry_ratio: 0.0,
      recurrence_probability: 1.0,
      verdict_reason: 'ASYMMETRY_REJECTED_UNSAFE: Violates hard invariant constraints (TLA+ fencing, CIF HMAC receipt).',
      permanent_dna_uri: 'mem://genesis/dna/rejected',
    };
  }

  if (proposal.founder_friction_cost > 0.0) {
    return {
      proposal_id: proposal.proposal_id,
      approved: false,
      computed_asymmetry_ratio: 0.0,
      recurrence_probability: 1.0,
      verdict_reason: `ASYMMETRY_REJECTED_FOUNDER_FRICTION: Introduces founder friction (${proposal.founder_friction_cost}). Must automate/dissolve constraint.`,
      permanent_dna_uri: 'mem://genesis/dna/rejected',
    };
  }

  const p_recur = getEnforcementRecurrenceProb(proposal.enforcement_mechanism);
  if (p_recur > 0.0 || proposal.class_cardinality_estimate <= 1) {
    return {
      proposal_id: proposal.proposal_id,
      approved: false,
      computed_asymmetry_ratio: 1.0,
      recurrence_probability: p_recur,
      verdict_reason: `POINT_FIX_REJECTED: Proposal is a linear point-fix (cardinality=${proposal.class_cardinality_estimate}, P_recur=${p_recur}). Generalize to class [p].`,
      permanent_dna_uri: 'mem://genesis/dna/rejected',
    };
  }

  if (proposal.wwfd_alignment_score < 0.95) {
    return {
      proposal_id: proposal.proposal_id,
      approved: false,
      computed_asymmetry_ratio: 0.0,
      recurrence_probability: p_recur,
      verdict_reason: `WWFD_ALIGNMENT_BELOW_THRESHOLD: Scored ${proposal.wwfd_alignment_score} (< 0.95 minimum) against Founder Utility Vector.`,
      permanent_dna_uri: 'mem://genesis/dna/rejected',
    };
  }

  const numerator =
    proposal.class_cardinality_estimate *
    proposal.expected_probes_saved_per_instance *
    (1.0 - p_recur);

  const denominator =
    Math.max(0.5, proposal.implementation_probe_cost) +
    FOUNDER_FRICTION_PENALTY_WEIGHT * proposal.founder_friction_cost;

  const ratio = Math.round((numerator / denominator) * 10) / 10;

  if (ratio < MIN_ASYMMETRY_RATIO) {
    return {
      proposal_id: proposal.proposal_id,
      approved: false,
      computed_asymmetry_ratio: ratio,
      recurrence_probability: p_recur,
      verdict_reason: `LOW_ASYMMETRY_LEVERAGE: Ratio ${ratio}x is below the ${MIN_ASYMMETRY_RATIO}x threshold.`,
      permanent_dna_uri: 'mem://genesis/dna/rejected',
    };
  }

  return {
    proposal_id: proposal.proposal_id,
    approved: true,
    computed_asymmetry_ratio: ratio,
    recurrence_probability: p_recur,
    verdict_reason: `APPROVED (${ratio}x Asymmetric Leverage): Permanently eliminated whole problem class '${proposal.problem_equivalence_class}' across the estate.`,
    permanent_dna_uri: `mem://genesis/dna/rules/${proposal.proposal_id}`,
  };
}

