export interface InstructionScenario {
  scenario_name: string;
  input_condition: string;
  expected_behavior: string;
  cif_receipt_target: string;
}

export interface ClarifiedInstructionSpec {
  raw_founder_prompt: string;
  inferred_protocol: string;
  formal_deconstruction: string;
  identified_ambiguities: string[];
  model_scenarios: InstructionScenario[];
  ready_for_execution: boolean;
}

export function ingestAndClarifyInstruction(rawPrompt: string): ClarifiedInstructionSpec {
  const lower = rawPrompt.toLowerCase();

  let inferred_protocol = 'PROTO_DECIDE_ON_DOSSIER';
  if (lower.includes('proto_build_api') || (lower.includes('api') && !lower.includes('ui')) || lower.includes('schema') || lower.includes('rust')) {
    inferred_protocol = 'PROTO_BUILD_API';
  } else if (lower.includes('proto_infra_lane') || lower.includes('lane') || lower.includes('nats') || lower.includes('sync') || lower.includes('oci')) {
    inferred_protocol = 'PROTO_INFRA_LANE';
  } else if (lower.includes('proto_web_surface') || lower.includes('ui') || lower.includes('cockpit') || lower.includes('component') || lower.includes('surface')) {
    inferred_protocol = 'PROTO_WEB_SURFACE';
  } else if (lower.includes('fmea') || lower.includes('failure') || lower.includes('diagnose')) {
    inferred_protocol = 'PROTO_FMEA_CURATION';
  }

  const ambiguities: string[] = [];
  if (!lower.includes('lane') && !lower.includes('component') && !lower.includes('ticket')) {
    ambiguities.push('Target component or lane ID is underspecified; defaulting to active lane LANE_C_MAC / LANE_A_GCP.');
  }
  if (!lower.includes('test') && !lower.includes('verify') && !lower.includes('receipt')) {
    ambiguities.push('Verification criteria not explicitly stated; defaulting to BDD failover tests + CIF HMAC receipt.');
  }

  const formal_deconstruction = `Formalized instruction under protocol [${inferred_protocol}]: Executing deterministic state transition with Pass 0 self-diagnosis and verified CIF HMAC receipt.`;

  const model_scenarios: InstructionScenario[] = [
    {
      scenario_name: 'Happy Path (Standard Execution)',
      input_condition: `Raw prompt '${rawPrompt.slice(0, 48)}...' parsed with valid vault secrets and active Tailscale mesh.`,
      expected_behavior: 'Pass 0 diagnosis succeeds, protocol binds, composite action executes in 1 batched pass.',
      cif_receipt_target: 'EXIT 0 | VERIFIED | HMAC Match',
    },
    {
      scenario_name: 'Edge Case (Ambiguity / Friction In-Flight)',
      input_condition: 'Target file locked or non-fast-forward git divergence detected mid-execution.',
      expected_behavior: 'Asymmetry Engine intercepts point-fix, applies structural remediation class, and updates L0 memory.',
      cif_receipt_target: 'EXIT 0 | ASYMMETRIC_REMEDIATION_APPLIED',
    },
  ];

  return {
    raw_founder_prompt: rawPrompt,
    inferred_protocol,
    formal_deconstruction,
    identified_ambiguities: ambiguities,
    model_scenarios,
    ready_for_execution: ambiguities.length === 0,
  };
}

