export function evaluateOrganismHarmonics(organs: OrganismOrgan[]): OrganismHarmonicState {
  const count = organs.length || 1;
  const avgBpm = Math.round(organs.reduce((sum, o) => sum + o.bpm, 0) / count);
  const avgArrhythmia = Number((organs.reduce((sum, o) => sum + o.arrhythmiaIndex, 0) / count).toFixed(3));
  const preSymptomCount = organs.filter((o) => o.healthState === 'PRE_SYMPTOM_TREMOR' || o.healthState === 'ARRHYTHMIC_BRUISE').length;

  let harmonicChord = 'C-MAJOR-PENTATONIC-432HZ';
  let isHarmonic = true;
  let posture = 'Calm, synchronized respiratory rhythm. Vascular flow laminar with zero backpressure.';

  if (avgArrhythmia > 0.35 || preSymptomCount >= 3) {
    harmonicChord = 'DIMINISHED_TRITONE_DISSONANCE';
    isHarmonic = false;
    posture = 'Arrhythmic membrane twitching detected. Cellular hypoxia in downstream services; bruised vascular splines.';
  } else if (avgArrhythmia > 0.08 || preSymptomCount >= 1) {
    harmonicChord = 'SUSPENDED_FOURTH_TENSION';
    isHarmonic = false;
    posture = 'Pre-symptom micro-tremors observed. Early queue friction localized in delivery lanes before SLA drop.';
  }

  const breathingHz = Number((avgBpm / 240).toFixed(2));
  const attestation = sha256Hex(`ORGANISM_HARMONIC_STATE:${avgBpm}:${avgArrhythmia}:${harmonicChord}`);

  return {
    globalBpm: avgBpm,
    breathingCycleHz: breathingHz,
    harmonicChord,
    isSonificationHarmonic: isHarmonic,
    aggregateArrhythmiaScore: avgArrhythmia,
    preSymptomTremorCount: preSymptomCount,
    postureDescription: posture,
    cifHashAttestation: attestation,
  };
}

export function simulateOrganismCounterfactual(
  preset: 'NORMAL_RESTING_HARMONY' | 'CI_FLAKE_IRREGULAR_TAP' | 'SPLIT_BRAIN_ZOMBIE_TREMOR' | 'ASYMMETRIC_COMPOUNDING_CURE',
  baseOrgans: OrganismOrgan[] = INITIAL_ORGANISM_ORGANS
): { updatedOrgans: OrganismOrgan[]; harmonics: OrganismHarmonicState } {
  const updatedOrgans: OrganismOrgan[] = baseOrgans.map((organ) => {
    switch (preset) {
      case 'CI_FLAKE_IRREGULAR_TAP':
        if (organ.id === 'GITOPS_LITESTREAM') {
          return {
            ...organ,
            bpm: 96,
            arrhythmiaIndex: 0.22,
            healthState: 'PRE_SYMPTOM_TREMOR',
            membraneHue: '#eab308',
            vascularFlowRate: 42.0,
          };
        }
        return organ;

      case 'SPLIT_BRAIN_ZOMBIE_TREMOR':
        if (organ.id === 'NATS_VASCULAR' || organ.id === 'OTTO_SYNAPSE' || organ.id === 'ORACLE_CORE') {
          return {
            ...organ,
            bpm: 132,
            arrhythmiaIndex: 0.68,
            healthState: 'ARRHYTHMIC_BRUISE',
            membraneHue: '#ef4444',
            vascularFlowRate: 4.8,
          };
        }
        return organ;

      case 'ASYMMETRIC_COMPOUNDING_CURE':
        return {
          ...organ,
          bpm: 60,
          arrhythmiaIndex: 0.01,
          healthState: 'VIBRANT_HARMONY',
          membraneHue: organ.category === 'CORE_BRAIN' ? '#10b981' : organ.membraneHue,
          vascularFlowRate: 20.0,
        };

      case 'NORMAL_RESTING_HARMONY':
      default:
        return {
          ...organ,
          bpm: 64,
          arrhythmiaIndex: 0.02,
          healthState: 'VIBRANT_HARMONY',
        };
    }
  });

  const harmonics = evaluateOrganismHarmonics(updatedOrgans);
  return { updatedOrgans, harmonics };
}

